__NUXT_JSONP__("/think-tanks/columnas/the_global_south_perspective_through_g20_recommendations_from_the_think_tank_20", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K,L,M,N,O){return {data:[{post:{slug:"the_global_south_perspective_through_g20_recommendations_from_the_think_tank_20",title:"The Global South perspective through G20: recommendations from the Think Tank 20",date:"2024-07-22T21:24:44.297Z",img:"https:\u002F\u002Fucarecdn.com\u002F1a583a81-bf17-45ee-8238-284d468c3861\u002F",autor:"Javier González y José Francisco García",medio:"Southern Voice",link:"https:\u002F\u002Fsouthernvoice.org\u002Fthe-global-south-perspective-through-g20-recommendations-from-the-think-tank-20\u002F",category:n,extracto:"In this piece, we aim to outline the recommendations  of the Think Tank 20 (T20) engagement group to G20 leaders and negotiators, which were formally issued in the T20 2024 Communiqué during the Midterm Conference on July 2nd and 3rd 2024.",toc:[{id:x,depth:q,text:y},{id:z,depth:q,text:A},{id:B,depth:q,text:C}],body:{type:m,children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"During this year’s Brazil G20 presidency, inequalities in the Global South are a central focus of discussion. This space is an opportunity for the countries of the Global South to place their priorities on the world agenda from a perspective focused on respecting differences and joining efforts in common challenges. In this piece, we aim to outline the recommendations  of the Think Tank 20 (T20) engagement group to G20 leaders and negotiators, which were formally issued in the "},{type:b,tag:k,props:{},children:[{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.t20brasil.org\u002Fen\u002Fcommunique",rel:[g,h,i],target:j},children:[{type:a,value:"T20 2024 Communiqué"}]}]},{type:a,value:" during the Midterm Conference on July "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.youtube.com\u002Fwatch?v=0jinYvfKWuM",rel:[g,h,i],target:j},children:[{type:a,value:"2nd"}]},{type:a,value:" and "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.youtube.com\u002Fwatch?v=iqaTx4V30_U",rel:[g,h,i],target:j},children:[{type:a,value:"3rd "}]},{type:a,value:"2024. We analyse some implications of the recommendations to Global South countries around task forces 1 and 2*: “Combating poverty, hunger and inequality”* and “"},{type:b,tag:k,props:{},children:[{type:a,value:"Sustainable climate action and inclusive just energy transitions”"}]},{type:a,value:"."}]},{type:a,value:c},{type:b,tag:r,props:{id:x},children:[{type:b,tag:f,props:{href:"#combating-poverty-hunger-and-inequality",ariaHidden:s,tabIndex:t},children:[{type:b,tag:u,props:{className:[v,w]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:y}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The G20 should bolster the "},{type:b,tag:e,props:{},children:[{type:a,value:"Global Alliance against Hunger and Poverty"}]},{type:a,value:" proposed by Brazil, ensuring alignment with the Sustainable Development Goals (SDGs). This promotes multilateral cooperation, leveraging financial resources and knowledge, sustainable food systems, and social protection. For the Global South, it offers opportunities for funding, technology transfer, and technical assistance, focusing on local production to reduce environmental damage and food insecurity."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Providing "},{type:b,tag:e,props:{},children:[{type:a,value:"long-term care policies"}]},{type:a,value:" that reinforce basic human rights, and developing and professionalising the care economy are important priorities. Challenges are significantly  different from region to region, so public policies must account for this diversity. For instance, most of the Global South lags in implementing policies that promote the active participation of men in care tasks and that enable women to balance care activities with paid employment."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Regarding the "},{type:b,tag:e,props:{},children:[{type:a,value:"unequal access to healthcare"}]},{type:a,value:", the G20 should advocate for technology transfer and cooperation to strengthen health systems, particularly in vulnerable regions of Global South countries. This aims to address gaps by improving healthcare accessibility, enhancing pandemic readiness, linking climate change with sanitary risks, and bridging digital divides. Progressive taxation fiscal policies are also needed to strengthen social protection systems and combat inequalities, fight poverty, and social exclusion."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The G20 is prompted to foster a "},{type:b,tag:e,props:{},children:[{type:a,value:"global initiative on data generation"}]},{type:a,value:" for quantifying systemic inequalities and informing evidence-based policies. This initiative aims to strengthen policy frameworks and accountability, particularly in the Global South, enhancing data capabilities and addressing disparities among marginalised groups."}]},{type:a,value:c},{type:b,tag:r,props:{id:z},children:[{type:b,tag:f,props:{href:"#on-sustainable-climate-action-and-inclusive-just-energy-transitions",ariaHidden:s,tabIndex:t},children:[{type:b,tag:u,props:{className:[v,w]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:A}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"Fostering a just dimension of energy transition"}]},{type:a,value:" involves the development of holistic transition plans, climate adaptation, biodiversity preservation, and universal access to clean and affordable energy. From our perspective at Ethos, special emphasis should be placed in the future on adaptation policies and measures, since the permanent nature of the health, climate and environmental crises forces us to structurally modify our development models, particularly for Global South countries. The G20 should foster coordination and equitable funding. It should include building institutional capacity, enhancing South-South and North-South cooperation for technology transfer, and developing grants-based finance mechanisms. This approach would benefit the low- and middle-income countries to face the challenges of decarbonization. However, cooperation must be conducted equitably, avoiding the imposition of actions and considering the characteristics of each context."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The "},{type:b,tag:e,props:{},children:[{type:a,value:"reform of"}]},{type:a,value:" "},{type:b,tag:e,props:{},children:[{type:a,value:"Multilateral Development Banks (MDBs) and Multilateral Climate Funds"}]},{type:a,value:" should focus on ensuring justice and inclusiveness in funding allocation, particularly for climate adaptation. This involves simplifying finance accessibility, ensuring transparency, providing concessional funding, and standardizing allocation criteria to prioritize low-income countries, disadvantaged groups, and small businesses. These initiatives are aimed to support Global South countries to access climate finance without exacerbating financial constraints."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"Placing traditional communities at the core of the design and implementation of relevant instruments"}]},{type:a,value:" involves incorporating indigenous knowledge and participatory governance in bioeconomy strategies to protect the ecosystems. Equitable benefit-sharing with indigenous people and traditional communities holds relevance for the sustainable and equitable development of Global South countries, given their cultural and territorial richness. However, it poses coordination challenges, at national and international levels."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"A fairer international tax system and subsidy reusing to ensure climate justice"}]},{type:a,value:" includes establishing common roadmaps for repurposing fossil fuel subsidies, implementing fairer taxation on high-pollution corporations, and redirecting the revenue to sustainable development and climate action. This can potentially provide the means for just transitions and address the funding gaps faced by Global South countries in climate adaptation."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"Standardization of social and biodiversity objectives into green taxonomies, sustainability frameworks, and ESG metrics,"}]},{type:a,value:" aims to implement social and sustainability criteria in businesses and financial institutions. Fostering sustainable supply chains, industry decarbonization, and quality job creation, benefits Global South countries. It facilitates access to financial markets and supports sustainable economic growth."}]},{type:a,value:c},{type:b,tag:r,props:{id:B},children:[{type:b,tag:f,props:{href:"#final-remarks",ariaHidden:s,tabIndex:t},children:[{type:b,tag:u,props:{className:[v,w]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:C}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Adopting the SDGs across countries with diverse contexts, cultures, policy traditions and development models remains a contentious issue. It is usually overshadowed by economic priorities and geopolitical interests. Hence, it is crucial to foster a justice-centred approach, prioritising cooperation to meet the specific needs of each country, as well as promoting fair funding to the Global South."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The recent and near future presidencies of the G20 mark a period in which Global South countries are increasingly playing a significant role in global decision-making. The T20 contributes to this direction. It highlights opportunities for the inclusion and participation of countries that have been historically negatively affected by capitalism and globalization. It is through unified efforts that they can better advocate their interests, address common challenges and contribute to shape a more equitable and sustainable global landscape."}]},{type:a,value:c}]},dir:o,path:"\u002Fcolumnas\u002Fthe_global_south_perspective_through_g20_recommendations_from_the_think_tank_20",extension:p,createdAt:D,updatedAt:D},columnas:[{slug:"collaboration_under_the_mantle_of_populism",title:"Collaboration under the mantle of populism",date:"2025-07-10T17:20:20.737Z",img:"https:\u002F\u002Fucarecdn.com\u002F2c75323d-b65f-4d5a-8e29-fa2c0b7f4977\u002F","img-alt":"colaboración",autor:"Liliana Alvarado ",medio:"On Think Tanks",link:"https:\u002F\u002Fonthinktanks.org\u002Farticles\u002Fcollaboration-under-the-mantle-of-populism\u002F",category:n,extracto:E,toc:[],body:{type:m,children:[{type:b,tag:d,props:{},children:[{type:a,value:"In general terms, collaboration involves establishing a relationship with other actors —whether similar or different— with the aim of achieving a specific goal. In order for collaboration to be effective, there are several elements that must be in place: (1) a shared objective, (2) transparent and fluid communication, (3) an environment of mutual trust, and (4) a favorable context. Collaboration tends to be more successful when the benefits are clear or when it addresses a pressing need of the parties involved."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"In practice, the contextual factor has proven to carry significant weight. In the specific case of the Latin American region, some populist governments—whether left- or right-leaning—have sought to divide their populations in various ways (rich vs. poor, right vs. left, liberals vs. conservatives). Generally speaking, these labels have been used by such regimes to separate the “good” from the “bad”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"According to this perspective, the “bad guys” are all those individuals or groups who think differently from the government or ruling party. As a result, criticism of government actions—or demands for openness, transparency, and accountability—can often be met with hostility. This undoubtedly hinders the work of counterweights, which include autonomous or independent entities, the business sector, journalists, and research centres known as think tanks."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"In the case of the organisations mentioned above, they face a twofold challenge that negatively affects their work. The first is the difficulty in maintaining open communication channels, establishing relationships, or collaborating with the current government. This engagement—so crucial for achieving policy impact—becomes nearly impossible. The second issue lies in the difficulty of fostering collaboration among non-governmental actors themselves, such as civil society organisations, the private sector, universities, and the media. All of these stakeholders play a key role in advancing advocacy strategies that seek to drive policy change."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:E}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"At times, the political and economic influence of third countries also affects collaboration. In this regard, funding from international development agencies to think tanks has been shifting significantly over the last few years. In several countries, these funds have been reduced and are now granted for shorter periods, forcing organisations to continually search for resources. This situation was further exacerbated by the “Trump factor,” as the U.S. president had earlier decided to eliminate foreign aid provided by the United States Agency for International Development (USAID) to other countries."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Currently, securing three or four separate funding sources may be necessary to cover what was once achieved with just one. This resource scarcity has made it increasingly difficult to form consortia to access funding. While some donors encourage collaboration among two or more think tanks to design and implement projects, the overall reduction in available resources has made it less feasible to split funding among multiple parties."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"It seems that both national and international contexts are undermining collaborative efforts. In the case of think tanks, this has led to new challenges in how they operate, particularly in certain regions of the world. Yet, working in isolation does not appear to be a viable alternative either. Will it become increasingly common for think tanks to form alliances with actors from opposing ideological backgrounds? Is it possible for civil society organizations to collaborate with governments they do not trust —or that seek to delegitimize their work? Where should we draw the line between a healthy diversity of perspectives and the values that a collaboration can tolerate without compromising its purpose?"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Think tanks are at a crossroads where they must determine whether a less genuine and sincere form of collaboration is still desirable, or at least strategically necessary. This dilemma applies not only to relationships with incumbent governments but also to those with non-governmental actors. Do the ends justify the means? There is no definitive answer. In some cases, populism and its effects have been gradually expanding, prompting think tanks to adapt to shifting dynamics and to test various strategies in an effort to understand what works and what does not."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"It is challenging to predict the future of collaboration under the influence of populism, which is increasingly drawing more people into its sphere. In this context, think tanks must find ways to remain relevant and loyal to their principles, without legitimising positions that are eroding democratic institutions. The challenge lies in not losing sight of what gives meaning to their existence: contributing to the public interest through research and independent thinking."}]}]},dir:o,path:"\u002Fcolumnas\u002Fcollaboration_under_the_mantle_of_populism",extension:p,createdAt:F,updatedAt:F},{slug:"cuatro_formas_creativas_en_las_que_colaboran_los_think_tanks_con_periodistas",title:"CUATRO FORMAS CREATIVAS EN LAS QUE COLABORAN LOS THINK TANKS CON PERIODISTAS ",date:"2018-11-13T00:03:36.335Z",img:"https:\u002F\u002Fucarecdn.com\u002F0cca2aa0-fe73-4d2d-ab07-2ae60d598681\u002F",autor:"Ethos",medio:G,link:"https:\u002F\u002Fwww.arenapublica.com\u002Fblog-ethos-laboratorio\u002Fthink-tanks-y-periodistas-4-formas-de-colaboracion",category:n,extracto:"Los *think tanks* a nivel global tenemos problemas para comunicar lo que hacemos. Muchas veces cuando les contamos a nuestros amigos y familiares sobre nuestro trabajo, las reacciones más frecuentes son: “¿*think* qué?”, “¿en qué piensan?”, “¿tanque? debe estar relacionado con las fuerzas armadas”.",toc:[],body:{type:m,children:[{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:"Los think tanks se enfrentan al reto de difundir los conocimientos que producen. A través de diversas estrategias innovadoras pueden generar una comunicación efectiva con la sociedad."}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Los "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" a nivel global tenemos problemas para comunicar lo que hacemos. Muchas veces cuando les contamos a nuestros amigos y familiares sobre nuestro trabajo, las reacciones más frecuentes son: “¿"},{type:b,tag:k,props:{},children:[{type:a,value:"think"}]},{type:a,value:" qué?”, “¿en qué piensan?”, “¿tanque? debe estar relacionado con las fuerzas armadas”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A nivel mundial, muchos centros de pensamiento y estudios, organismos de desarrollo y otros, "},{type:b,tag:e,props:{},children:[{type:a,value:"no logramos comunicar el conocimiento que generamos"}]},{type:a,value:". Entre una serie de Netflix, o los feeds de las redes sociales, y un estudio de políticas públicas, ¿qué escogería consumir usted? El Banco Mundial hizo un "},{type:b,tag:f,props:{href:"http:\u002F\u002Fdocuments.worldbank.org\u002Fcurated\u002Fen\u002F387501468322733597\u002Fpdf\u002FWPS6851.pdf",rel:[g,h,i],target:j},children:[{type:a,value:"estudio"}]},{type:a,value:" hace unos años en el que encontró que el 31% de sus documentos nunca habían sido descargados. Y se trata de textos dirigidos a expertos que deberían preferir la lectura de dichos documentos, frente a ver La Casa de las Flores."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Si el Banco Mundial es una de las instituciones con más recursos y especialistas para generar y difundir conocimiento sobre desarrollo económico y político, ¿qué podemos hacer instituciones mucho más pequeñas y sin tantos recursos para llegar a tener más influencia? Felizmente, en México hay muchos casos de innovación que responden cómo hacerlo, provenientes de "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" y organizaciones similares. Se trata de "},{type:b,tag:e,props:{},children:[{type:a,value:"alianzas con medios creativos, trabajo colaborativo con periodistas de investigación, uso de herramientas tecnológicas"}]},{type:a,value:", entre otros. Acá les damos 4 ejemplos sobre cómo lograrlo:"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:H}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“"},{type:b,tag:e,props:{},children:[{type:a,value:"PAOLA"}]},{type:a,value:". Era trabajadora sexual. Fue asesinada hace dos años en el coche de un cliente. "},{type:b,tag:e,props:{},children:[{type:a,value:"El principal sospechoso, un exmilitar, sigue prófugo"}]},{type:a,value:".”"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para difundir su reporte "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.mexicoevalua.org\u002Fwp-content\u002Fuploads\u002F2018\u002F09\u002F5013HomicidiosCDMX.pdf",rel:[g,h,i],target:j},children:[{type:a,value:H}]},{type:a,value:", "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.mexicoevalua.org\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"México Evalúa"}]},{type:a,value:" creó una alianza con El País, de lo cual resultó el reportaje "},{type:b,tag:f,props:{href:"https:\u002F\u002Felpais.com\u002Fespeciales\u002F2018\u002Fviolencia-cdmx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Matar o morir"}]},{type:a,value:". La plataforma enlaza testimonios, numeralias, videos, frases y gráficas interactivas, lo que da un sentido más humano al informe."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Asimismo, Fusión generó "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.facebook.com\u002FFusionMexicoOficial\u002Fvideos\u002F732797000392788\u002FUzpfSTEwMDAwMjYzMjY5MjYwODoxNzY0MjUyNjAwMzM5MTQ2\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"minidocumentales"}]},{type:a,value:" y México.com publicó una serie de "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.mexico.com\u002Fespecial\u002Fhomicidios-en-cdmx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"reportajes"}]},{type:a,value:" relacionados con el contenido del informe."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"La Estafa Maestra"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Sabemos que hay muchísima corrupción. Pero como es un fenómeno que se hace a escondidas y se trata de ocultar por todos los medios posibles, no es fácil encontrar sus mecanismos ni descubrirla a la opinión pública. Sin embargo, "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.animalpolitico.com\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Animal Político"}]},{type:a,value:I},{type:b,tag:f,props:{href:J,rel:[g,h,i],target:j},children:[{type:a,value:K}]},{type:a,value:"(MCCI) hicieron exactamente eso: "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.animalpolitico.com\u002Festafa-maestra\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"revelaron que dependencias del Gobierno Federal"}]},{type:a,value:" y universidades públicas "},{type:b,tag:e,props:{},children:[{type:a,value:"desviaron 7,670 millones de pesos"}]},{type:a,value:" en contratos ilegales a 186 empresas, de la cuales 128 eran empresas fantasma."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El equipo de periodistas presentó la información con un formato interactivo y transmedia. Empleó videos, testimoniales, un cómic, infografías, numeralias y hasta emojis. Además vincularon a los becarios del programa Prensa y Democracia ("},{type:b,tag:f,props:{href:"https:\u002F\u002Ftwitter.com\u002Fprogramaprende?lang=es",rel:[g,h,i],target:j},children:[{type:a,value:"PRENDE"}]},{type:a,value:") de la "},{type:b,tag:f,props:{href:"http:\u002F\u002Fibero.mx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Universidad Iberoamericana"}]},{type:a,value:" para colaborar en la investigación. Gracias a este trabajo, la Auditoría Superior de la Federación reconoció esta red de corrupción y el Servicio de Administración Tributaria inició una investigación contra empresas fantasma."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:"Por qué se cayó mi edificio"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Los habitantes en la Ciudad de México saben qué hacer durante un sismo; cómo salir de un departamento o dónde resguardarse mejor. Quienes han fallado han sido las autoridades.”"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A través de un trabajo colaborativo entre la ciudadanía, investigadores y periodistas, "},{type:b,tag:f,props:{href:J,rel:[g,h,i],target:j},children:[{type:a,value:K}]},{type:a,value:"presentó un "},{type:b,tag:f,props:{href:"https:\u002F\u002Fmiedificio.contralacorrupcion.mx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"micrositio"}]},{type:a,value:" que incluye un "},{type:b,tag:e,props:{},children:[{type:a,value:"recorrido por 28 construcciones"}]},{type:a,value:" en las que se detectaron actos de corrupción. A través de ilustraciones, fotografías y el uso del periodismo narrativo se entiende lo vivido en cada una de ellas.  Y se demuestra que el fallecimiento de muchas personas y daños provocados por el sismo del 19 de septiembre de 2017 pudieron haberse evitado si se respetaran las reglas para realizar construcciones."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:e,props:{},children:[{type:a,value:L}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La designación de los funcionarios públicos en México sigue siendo una área gris sobre la que "},{type:b,tag:f,props:{href:"http:\u002F\u002Ffundar.org.mx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Fundar"}]},{type:a,value:I},{type:b,tag:f,props:{href:"https:\u002F\u002Farticulo19.org\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Artículo 19"}]},{type:a,value:" pusieron el ojo para tratar de echar abajo “el dedazo” en la asignación de puestos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Desde 2012 y hasta la fecha, activistas, investigadores y periodistas trabajan en el proyecto "},{type:b,tag:f,props:{href:"https:\u002F\u002Fdesignaciones.org\u002Ffederales\u002F#!\u002Fprincipal",rel:[g,h,i],target:j},children:[{type:a,value:L}]},{type:a,value:" para "},{type:b,tag:e,props:{},children:[{type:a,value:"analizar los procesos de selección de los titulares de las instituciones"}]},{type:a,value:". Los objetivos están claros: primero, contar con mayor transparencia y participación ciudadana en los nombramientos; y, segundo, que las personas que ocupan los cargos públicos tengan experiencia y cuenten con capacidad probada en el tema."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Publicado en: "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.arenapublica.com\u002Fblog-ethos-laboratorio\u002Fcuatro-formas-creativas-en-las-que-colaboran-los-think-tanks-con-periodistas",rel:[g,h,i],target:j},children:[{type:a,value:G}]}]}]},dir:o,path:"\u002Fcolumnas\u002Fcuatro_formas_creativas_en_las_que_colaboran_los_think_tanks_con_periodistas",extension:p,createdAt:"2023-06-19T05:11:57.687Z",updatedAt:M},{slug:"el_contrapeso_gubernamental_a_la_baja",description:"\nEn términos muy generales, los think tanks son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación. Algunas organizaciones cuentan con cientos de empleados, sin embargo, el equipo de otros apenas se cuenta con los dedos de una mano.",title:"¿EL CONTRAPESO GUBERNAMENTAL A LA BAJA?",date:"2022-02-22T23:44:29.610Z",img:"https:\u002F\u002Fucarecdn.com\u002F1fd5c811-6354-462c-b33a-04b627a7742d\u002F",autor:"Liliana Alvarado",medio:"El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002FEl-contrapeso-gubernamental-a-la-baja-20220222-0057.html",category:n,extracto:"En términos muy generales, los *think tanks* son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación",toc:[],body:{type:m,children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:N},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación. Algunas organizaciones cuentan con cientos de empleados, sin embargo, el equipo de otros apenas se cuenta con los dedos de una mano. "},{type:a,value:" Otra diferencia entre ellos es el tipo de relación que tienen con su respectivo gobierno. En algunos países los "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" asesoran y colaboran de forma cercana con las autoridades, pues se valora significativamente su capacidad y conocimiento técnico en las diferentes temáticas. No obstante, en otras naciones los "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" adquieren un papel de "},{type:b,tag:k,props:{},children:[{type:a,value:O}]},{type:a,value:", haciendo referencia a la figura de un perro guardián que tiene como objetivo realizar tareas de vigilancia y monitoreo. Es más común que las organizaciones tomen este papel cuando el país enfrenta debilidades importantes en materia de transparencia, rendición de cuentas, anticorrupción, entre otros temas que requieren un señalamiento o voz de denuncia."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En este sentido, los "},{type:b,tag:k,props:{},children:[{type:a,value:O}]},{type:a,value:" forman parte del conjunto de contrapesos al gobierno. A la lista se suman algunos medios de comunicación, periodistas, el empresariado, los organismos autónomos y electorales, entre otros. No obstante, de esta lista, tal vez uno de los contrapesos menos analizados y conocidos son los "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:". Ello se relaciona con el hecho de que su trabajo en ocasiones se confunde con el de la academia o incluso con organizaciones activistas."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Recientemente la plataforma global On Think Tanks presentó el Open Think Tanks Directory, que incluye un documento de análisis sobre los "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" en el continente americano. De acuerdo con el reporte, los temas más comunes que abordan las organizaciones en Latinoamérica y el Caribe (LAC) en orden de importancia son: medio ambiente, política social, gobernanza\u002Ftransparencia y justicia\u002Fderechos humanos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"No sorprende que en nuestra región algunas de las prioridades de las organizaciones sean los temas de gobernanza\u002Ftransparencia así como justicia\u002Fderechos humanos. Los problemas en dichos temas son profundos y se requiere mostrar con datos y evidencia cuáles son las áreas de mejora. Otro dato interesante del reporte se refiere al número de "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" en cada país: Brasil (65), Argentina (54), Chile (52) y México (43). En el otro extremo tenemos a países con un número muy reducido: Honduras (4), Nicaragua (3) y Belice (1). Un análisis más profundo nos permitiría conocer su antigüedad, presupuesto, fuentes de financiamiento, así como valorar el impacto e incidencia que tienen las organizaciones en las políticas públicas del país."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Cuando analizamos la tendencia de "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" creados por década y por región, se aprecia que, tanto en el mundo como en América del Norte y Latinoamérica, la creación de este tipo de instituciones va a la baja. Particularmente, en América Latina y el Caribe, la mayoría de este tipo de organizaciones se crearon entre 1990 y el 2009."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Dado este escenario, la pregunta adecuada sería ¿los think tanks como contrapeso, van a la baja? La respuesta es no. Hoy en día los "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" son más necesarios que nunca. En América Latina, por ejemplo, la corrupción no ha ido mejorando y tampoco lo han hecho temas como la seguridad, justicia, defensa de los derechos humanos, entre otros."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Lo que sí ha pasado es que las condiciones en las que trabajan los "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" y otros actores que son contrapeso del gobierno en la región, se han vuelto más difíciles. Actualmente en algunos países se condena a quienes los financian, se persigue a quienes los dirigen y se intimida a sus miembros. En un contexto como este, es fácil entender que Nicaragua, donde el presidente Daniel Ortega ha perseguido a opositores, disidentes y periodistas para mantenerse en el poder, solo tenga tres."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Hoy más que nunca hay que generar conciencia sobre la importancia de estas organizaciones. De manera particular, preocupa que con el paso del tiempo se están creando menos "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:". Las razones pueden ser diversas, sin embargo, el resultado es el mismo. Existen menos organizaciones en la región que están vigilando el actuar de los gobiernos y que están presionando para contar con mejores democracias, gobernanza y condiciones de vida para la población."}]},{type:a,value:c}]},excerpt:{type:m,children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:N},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación. Algunas organizaciones cuentan con cientos de empleados, sin embargo, el equipo de otros apenas se cuenta con los dedos de una mano."}]}]},dir:o,path:"\u002Fcolumnas\u002Fel_contrapeso_gubernamental_a_la_baja",extension:p,createdAt:"2023-06-19T05:11:57.867Z",updatedAt:M}]}],fetch:{},mutations:[]}}("text","element","\n","p","strong","a","nofollow","noopener","noreferrer","_blank","em","think tanks","root","think-tanks","\u002Fcolumnas",".md",2,"h2","true",-1,"span","icon","icon-link","combating-poverty-hunger-and-inequality","Combating poverty, hunger and inequality","on-sustainable-climate-action-and-inclusive-just-energy-transitions","On sustainable climate action and inclusive just energy transitions","final-remarks","Final Remarks","2024-10-02T22:32:44.076Z","The radicalisation and polarisation of perspectives hinder dialogue and consensus-building. This growing divide among actors is not only present in populist governments but also in other regimes undergoing processes of democratic backsliding, where core values such as freedom of expression, civic participation, the rule of law, and tolerance are increasingly undermined.","2025-11-25T01:24:03.234Z","Arena Pública","5013 homicidios en la Ciudad de México"," y ","https:\u002F\u002Fcontralacorrupcion.mx\u002F","Mexicanos contra la Corrupción y la Impunidad ","Designaciones públicas","2022-09-15T15:48:00.227Z","En términos muy generales, los ","watch dogs")));